const ENSEMBLE_RAIN_EXPORT_CHART_WIDTH=992;
const ENSEMBLE_TEMP_EXPORT_CHART_WIDTH=992;
const ENSEMBLE_WIND_EXPORT_CHART_WIDTH=992;
