function EnsembleExportHeader({kind,locationName}:{kind:EnsembleExportKind;locationName:string}){return <header className="ensemble-export-header"><span className="ensemble-export-kicker">MID · Meteorological Information Dashboard</span><strong>{locationName}</strong><span className="ensemble-export-subtitle">{kind==='temperature'?'14-Tage Temperatur-Ensemble':kind==='precipitation'?'14-Tage Niederschlags-Ensemble':'14-Tage Wind-Ensemble'}</span></header>}
